    fbBuilder.startTable(31);
    fbBuilder.addOffset(0, STATION_IDOffset);
    fbBuilder.addOffset(1, NAMEOffset);
    fbBuilder.addUint8(2, _NETWORK?.value);
    fbBuilder.addOffset(3, DOMES_NUMBEROffset);
    fbBuilder.addOffset(4, CDP_NUMBEROffset);
    fbBuilder.addUint8(5, _FRAME_REALIZATION?.value);
    fbBuilder.addOffset(6, FRAME_REALIZATION_NAMEOffset);
    fbBuilder.addOffset(7, REFERENCE_EPOCHOffset);
    fbBuilder.addFloat64(8, _POSITION_X);
    fbBuilder.addFloat64(9, _POSITION_Y);
    fbBuilder.addFloat64(10, _POSITION_Z);
    fbBuilder.addFloat64(11, _VELOCITY_X);
    fbBuilder.addFloat64(12, _VELOCITY_Y);
    fbBuilder.addFloat64(13, _VELOCITY_Z);
    fbBuilder.addFloat64(14, _POSITION_SIGMA_X);
    fbBuilder.addFloat64(15, _POSITION_SIGMA_Y);
    fbBuilder.addFloat64(16, _POSITION_SIGMA_Z);
    fbBuilder.addUint8(17, _ANTENNA_AXIS_TYPE?.value);
    fbBuilder.addFloat64(18, _AXIS_OFFSET_M);
    fbBuilder.addFloat64(19, _ECCENTRICITY_X);
    fbBuilder.addFloat64(20, _ECCENTRICITY_Y);
    fbBuilder.addFloat64(21, _ECCENTRICITY_Z);
    fbBuilder.addOffset(22, ECCENTRICITY_FRAMEOffset);
    fbBuilder.addOffset(23, TRANSMIT_BANDSOffset);
    fbBuilder.addOffset(24, RECEIVE_BANDSOffset);
    fbBuilder.addFloat64(25, _CLOCK_OFFSET_S);
    fbBuilder.addFloat64(26, _CLOCK_RATE_S_PER_S);
    fbBuilder.addOffset(27, CLOCK_TIME_SCALEOffset);
    fbBuilder.addOffset(28, VALID_FROMOffset);
    fbBuilder.addOffset(29, VALID_TOOffset);
    fbBuilder.addOffset(30, SOURCEOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
